package com.example.gym;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

public class MainActivity extends Activity {
    private JSONObject state; private LinearLayout body; private int plan=0, day=0, week=0, exercise=0; private boolean watch;
    @Override public void onCreate(Bundle b) { super.onCreate(b); watch=getPackageManager().hasSystemFeature("android.hardware.type.watch"); state=Store.read(this); home(); }
    @Override protected void onResume() { super.onResume(); JSONObject latest=Store.read(this); if(state!=null && latest.optLong("revision")>state.optLong("revision")) { state=latest; home(); } }
    private void persist() { try { state.put("revision",System.currentTimeMillis()); Store.save(this,state,true); } catch(Exception e) { error(e); } }
    private void error(Exception e) { Toast.makeText(this,e.getMessage()==null?"No se pudo completar":e.getMessage(),Toast.LENGTH_LONG).show(); }
    private void screen(String title) { ScrollView scroll=new ScrollView(this); body=new LinearLayout(this); body.setOrientation(LinearLayout.VERTICAL); int pad=watch?18:24; body.setPadding(pad,pad,pad,pad); scroll.addView(body); setContentView(scroll); text(title,watch?20:27); }
    private void text(String s,int size) { TextView t=new TextView(this); t.setText(s); t.setTextSize(size); t.setPadding(0,8,0,8); body.addView(t); }
    private void button(String label,Runnable action) { Button b=new Button(this); b.setText(label); b.setAllCaps(false); body.addView(b); b.setOnClickListener(v->action.run()); }
    private void choices(String title,String[] items,java.util.function.IntConsumer action) { new AlertDialog.Builder(this).setTitle(title).setItems(items,(d,n)->action.accept(n)).setNegativeButton("Cancelar",null).show(); }
    private JSONObject obj(JSONArray a,int i) { return a.optJSONObject(i); }
    private JSONArray plans() { return Store.array(state,"plans"); }
    private JSONObject active() { return state.optJSONObject("active"); }
    private void home() { screen("Mi entrenamiento"); if(active()!=null) button("Continuar sesión",()->workout()); if(!watch) button("Importar plan Excel",()->{ Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT); i.setType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"); i.addCategory(Intent.CATEGORY_OPENABLE); startActivityForResult(i,1); }); if(plans().length()>0) button("Nueva sesión",this::choosePlan); else text(watch?"Importá un plan en el teléfono y esperá la sincronización.":"Importá el plan de tu entrenador para comenzar.",16); button("Historial",this::history); text("Los datos se guardan en este dispositivo.",14); }
    @Override protected void onActivityResult(int request,int result,Intent data) { super.onActivityResult(request,result,data); if(request!=1||result!=RESULT_OK||data==null) return; try(java.io.InputStream in=getContentResolver().openInputStream(data.getData())) { JSONArray parsed=Workbook.parse(in); state.put("plans",parsed); persist(); home(); Toast.makeText(this,"Plan importado",Toast.LENGTH_SHORT).show(); } catch(Exception e) { error(e); } }
    private void choosePlan() { JSONArray a=plans(); String[] names=new String[a.length()]; for(int i=0;i<names.length;i++) names[i]=obj(a,i).optString("name"); choices("Elegí un plan",names,n->{plan=n;chooseDay();}); }
    private void chooseDay() { JSONArray a=Store.array(obj(plans(),plan),"days"); String[] names=new String[a.length()]; for(int i=0;i<names.length;i++) names[i]=obj(a,i).optString("name"); choices("Elegí un día",names,n->{day=n; choices("Semana",new String[]{"1","2","3","4","5"},w->{week=w; start();});}); }
    private void start() { if(active()!=null) { new AlertDialog.Builder(this).setMessage("Ya hay una sesión activa. Finalizala antes de empezar otra.").setPositiveButton("OK",null).show(); return; } try { JSONObject d=obj(Store.array(obj(plans(),plan),"days"),day); JSONArray source=Store.array(d,"exercises"), items=new JSONArray(); for(int i=0;i<source.length();i++) { JSONObject e=obj(source,i); JSONObject w=obj(Store.array(e,"weeks"),week); int sets=3; try { sets=Math.max(1,Math.min(30,(int)Double.parseDouble(w.optString("sets","3")))); } catch(Exception ignored) {} items.put(new JSONObject().put("name",e.optString("name")).put("code",e.optString("code")).put("sets",sets).put("done",new JSONArray()).put("reps",w.optString("reps")).put("load",w.optString("load")).put("video",e.optString("video"))); } state.put("active",new JSONObject().put("name",d.optString("name")).put("week",week+1).put("started",System.currentTimeMillis()).put("items",items).put("index",0)); persist(); workout(); } catch(Exception e) { error(e); } }
    private void workout() { JSONObject a=active(); if(a==null) {home();return;} JSONArray items=Store.array(a,"items"); if(items.length()==0) { screen("Sesión vacía"); button("Finalizar",this::finishSession); return; } exercise=Math.max(0,Math.min(items.length()-1,a.optInt("index"))); JSONObject e=obj(items,exercise); JSONArray done=Store.array(e,"done"); screen(a.optString("name")+" · Semana "+a.optInt("week")); text((exercise+1)+" / "+items.length()+"  "+e.optString("code")+" "+e.optString("name"),watch?17:22); text("Series: "+done.length()+" / "+e.optInt("sets")+" · quedan "+Math.max(0,e.optInt("sets")-done.length()),16); text("Reps: "+e.optString("reps","—")+"  Carga: "+e.optString("load","—"),15);
        if(done.length()<e.optInt("sets")) button("Completar serie",()->{ try { done.put(new JSONObject().put("at",System.currentTimeMillis())); e.put("done",done); persist(); workout(); } catch(Exception ex){error(ex);} });
        if(done.length()>0) button("Deshacer última serie",()->{done.remove(done.length()-1); persist(); workout();});
        if(exercise>0) button("← Anterior",()->move(-1)); if(exercise<items.length()-1) button("Siguiente →",()->move(1)); button("Descanso",this::rest); button("Cómo me sentí en este ejercicio",()->effort(e,()->workout()));
        if(!watch) { button("Video del ejercicio",()->video(e)); button("Editar datos del ejercicio",()->edit(e)); } else if(!e.optString("video").isEmpty()) text("Video disponible en el teléfono",14);
        button("Finalizar sesión",this::finishSession); button("Inicio",this::home);
    }
    private void move(int amount) { try { active().put("index",exercise+amount); persist(); workout(); } catch(Exception e) {error(e);} }
    private void effort(JSONObject target,Runnable next) { choices("¿Cómo te sentiste?",new String[]{"Muy fácil","Fácil","Normal","Difícil","Muy difícil"},n->{try {target.put("feeling",n+1);persist();next.run();}catch(Exception e){error(e);}}); }
    private void finishSession() { new AlertDialog.Builder(this).setMessage("¿Finalizar esta sesión?").setNegativeButton("Cancelar",null).setPositiveButton("Finalizar",(d,n)->effort(active(),()->{try { JSONObject a=active(); a.put("finished",System.currentTimeMillis()); JSONArray history=Store.array(state,"history"); history.put(a); state.put("history",history); state.remove("active"); persist(); home(); }catch(Exception e){error(e);}})).show(); }
    private void history() { JSONArray h=Store.array(state,"history"); screen("Historial"); if(h.length()==0) text("Todavía no hay sesiones.",16); for(int i=h.length()-1;i>=0;i--) { JSONObject s=obj(h,i); String date=android.text.format.DateFormat.getDateFormat(this).format(new Date(s.optLong("finished"))); text(date+" · "+s.optString("name")+" · Semana "+s.optInt("week")+" · Sensación "+s.optInt("feeling")+"/5",16); } button("Inicio",this::home); }
    private void video(JSONObject e) { String url=e.optString("video"); if(url.isEmpty()) { Toast.makeText(this,"Agregá un enlace en Editar datos",Toast.LENGTH_LONG).show(); return; } try { Uri uri=Uri.parse(url); if(!"https".equalsIgnoreCase(uri.getScheme()) && !"http".equalsIgnoreCase(uri.getScheme())) throw new IllegalArgumentException("Usá un enlace http o https"); startActivity(new Intent(Intent.ACTION_VIEW,uri)); } catch(Exception ex){error(ex);} }
    private void edit(JSONObject e) { LinearLayout box=new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL); EditText reps=new EditText(this),load=new EditText(this),video=new EditText(this); reps.setHint("Repeticiones"); reps.setText(e.optString("reps")); load.setHint("Carga"); load.setText(e.optString("load")); video.setHint("Enlace de video https://..."); video.setText(e.optString("video")); box.addView(reps);box.addView(load);box.addView(video); new AlertDialog.Builder(this).setTitle("Editar ejercicio de esta sesión").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,n)->{try {e.put("reps",reps.getText().toString());e.put("load",load.getText().toString());e.put("video",video.getText().toString());persist();workout();}catch(Exception ex){error(ex);}}).show(); }
    private void rest() { choices("Descanso",new String[]{"30 segundos","60 segundos","90 segundos","120 segundos"},n->{long seconds=new int[]{30,60,90,120}[n]; screen("Descanso"); TextView timer=new TextView(this); timer.setTextSize(30); body.addView(timer); CountDownTimer countdown=new CountDownTimer(seconds*1000,1000){public void onTick(long ms){timer.setText((ms+999)/1000+" s");} public void onFinish(){timer.setText("Listo");}}; countdown.start(); button("Volver",()->{countdown.cancel();workout();}); }); }
    @Override public void onBackPressed() { home(); }
}
